import {useState} from "react";

export const AddNewArticle = ()=>{
    const [article, setArticle] = useState({
        title: '',
        content: '',
    });

    const handleInput = (e)=>{
        setArticle({
            ...article,
            [e.target.name]: e.target.value
        })
    }

    return <div>
        <form id="new-article-form">
            <input type="text" name="title" value={article.title} onInput={(e)=>{handleInput(e)}}/>
            <textarea>

            </textarea>
        </form>
    </div>
}
